import{_ as a,a0 as p,w as n,s as i,ao as m,I as d,x as t,a1 as s,A as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"Emacs 注释中的拼写检查 | LCTT x X-CMD","titleTemplate":false,"description":"Emacs 注释中的拼写检查 | LCTT (201909) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Emacs 注释中的拼写检查 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Emacs 注释中的拼写检查 | LCTT (201909) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201909/20190524 Spell Checking Comments","title":"Emacs 注释中的拼写检查","tag":"201909","desc":""},"relativePath":"201909/20190524 Spell Checking Comments.md","filePath":"[post].md"}'),r={name:"201909/20190524 Spell Checking Comments.md"};function f(u,e,g,c,C,k){const o=p("Link");return n(),i("div",null,[e[15]||(e[15]=m('<h1 id="emacs-注释中的拼写检查" tabindex="-1">Emacs 注释中的拼写检查 <a class="header-anchor" href="#emacs-注释中的拼写检查" aria-label="Permalink to “Emacs 注释中的拼写检查”">​</a></h1><p>我出了名的容易拼错单词（特别是在播客当中）。谢天谢地 Emacs 内置了一个名为 <code>flyspell</code> 的超棒模式来帮助像我这样的可怜的打字员。flyspell 会在你输入时突出显示拼错的单词 (也就是实时的) 并提供有用的快捷键来快速修复该错误。</p><p>大多输入通常会对派生自 <code>text-mode</code>（比如 <code>markdown-mode</code>，<code>adoc-mode</code> ）的主模式启用 <code>flyspell</code>，但是它对程序员也有所帮助，可以指出他在注释中的错误。所需要的只是启用 <code>flyspell-prog-mode</code>。我通常在所有的编程模式中（至少在 <code>prog-mode</code> 派生的模式中）都启用它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>(add-hook &#39;prog-mode-hook #&#39;flyspell-prog-mode)</span></span></code></pre></div><p>现在当你在注释中输入错误时，就会得到即时反馈了。要修复单词只需要将光标置于单词后，然后按下 <code>C-c $</code> （<code>M-x flyspell-correct-word-before-point</code>）。（还有许多其他方法可以用 <code>flyspell</code> 来纠正拼写错误的单词，但为了简单起见，我们暂时忽略它们。）</p><p><img src="https://emacsredux.com/assets/images/flyspell_prog_mode.gif" alt="flyspell_prog_mode.gif"></p><p>今天的分享就到这里！我要继续修正这些讨厌的拼写错误了！</p><hr>',8)),d("p",null,[e[1]||(e[1]=t("via: ",-1)),s(o,{href:"https://emacsredux.com/blog/2019/05/24/spell-checking-comments/"},{default:l(()=>[...e[0]||(e[0]=[t("https://emacsredux.com/blog/2019/05/24/spell-checking-comments/",-1)])]),_:1})]),d("p",null,[e[6]||(e[6]=t("作者：",-1)),s(o,{href:"https://emacsredux.com"},{default:l(()=>[...e[2]||(e[2]=[t("Bozhidar Batsov",-1)])]),_:1}),e[7]||(e[7]=t(" 选题：",-1)),s(o,{href:"https://github.com/lujun9972"},{default:l(()=>[...e[3]||(e[3]=[t("lujun9972",-1)])]),_:1}),e[8]||(e[8]=t(" 译者：",-1)),s(o,{href:"https://github.com/lujun9972"},{default:l(()=>[...e[4]||(e[4]=[t("lujun9972",-1)])]),_:1}),e[9]||(e[9]=t(" 校对：",-1)),s(o,{href:"https://github.com/wxy"},{default:l(()=>[...e[5]||(e[5]=[t("wxy",-1)])]),_:1})]),d("p",null,[e[12]||(e[12]=t("本文由 ",-1)),s(o,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...e[10]||(e[10]=[t("LCTT",-1)])]),_:1}),e[13]||(e[13]=t(" 原创编译，",-1)),s(o,{href:"https://linux.cn/"},{default:l(()=>[...e[11]||(e[11]=[t("Linux中国",-1)])]),_:1}),e[14]||(e[14]=t(" 荣誉推出",-1))])])}const b=a(r,[["render",f]]);export{x as __pageData,b as default};
